'use strict';
let DATA,view='overview',page=0,query='';
const $=s=>document.querySelector(s),money=(c,d=0)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:d}).format(c/100),number=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(n),pct=n=>Number.isFinite(n)?(n*100).toFixed(1)+'%':'—';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sum=(a,k)=>a.reduce((s,r)=>s+(r[k]||0),0);
function filtered(month=$('#month').value){return DATA.daily.filter(r=>r.date.startsWith(month)&&($('#region').value==='All'||r.region===$('#region').value)&&($('#category').value==='All'||r.category===$('#category').value));}
function previous(){let [y,m]=$('#month').value.split('-').map(Number);return new Date(Date.UTC(y,m-2,1)).toISOString().slice(0,7);}
function totals(a){return {rev:sum(a,'revenue_cents'),profit:sum(a,'known_profit_cents'),missing:sum(a,'missing_cost_rows'),lines:sum(a,'line_count'),units:sum(a,'sale_units'),short:sum(a,'potential_shortfall_cents'),matched:sum(a,'matched_rows')};}
function kpi(label,value,detail,featured=false){return `<div class="card kpi ${featured?'featured':''}"><div class="label">${label}<span>↗</span></div><div class="value">${value}</div><div class="detail">${detail}</div></div>`;}
function trend(curr,prior){return prior?`<span class="${curr>=prior?'positive':'negative'}">${curr>=prior?'+':''}${pct((curr-prior)/Math.abs(prior))}</span> vs previous month`:'No comparison available';}
function lineChart(series,{moneyAxis=false,second=null,labels=true}={}){if(!series.length)return '<p>No data</p>';const w=680,h=220,p=34,vals=series.map(r=>r.value).concat(second?second.map(r=>r.value):[]),max=Math.max(...vals)*1.15||1;const pt=(v,i,n)=>[p+i*(w-2*p)/Math.max(n-1,1),h-p-v/max*(h-2*p)];const path=series.map((r,i)=>pt(r.value,i,series.length).join(',')).join(' ');let grid='';for(let i=0;i<4;i++){let v=max*i/3,y=pt(v,0,1)[1];grid+=`<line x1="${p}" x2="${w-p}" y1="${y}" y2="${y}"/><text x="2" y="${y-5}">${moneyAxis?money(v):number(v)}</text>`;}return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${moneyAxis?'Revenue':'Units'} trend chart">${grid}<polygon points="${p},${h-p} ${path} ${w-p},${h-p}" fill="#edf5ef"/><polyline points="${path}" fill="none" stroke="#2b7963" stroke-width="2.5"/>${second?`<polyline points="${second.map((r,i)=>pt(r.value,i,second.length).join(',')).join(' ')}" fill="none" stroke="#c49358" stroke-dasharray="5 4" stroke-width="2"/>`:''}${labels?`<text x="${p}" y="${h-8}">${esc(series[0].label)}</text><text x="${w-p}" text-anchor="end" y="${h-8}">${esc(series.at(-1).label)}</text>`:''}</svg>`;}
function aggregate(rows,key,value){const m={};rows.forEach(r=>m[r[key]]=(m[r[key]]||0)+(r[value]||0));return Object.entries(m).map(([label,value])=>({label,value}));}
function overview(){const rows=filtered(),t=totals(rows),p=totals(filtered(previous())),daily=aggregate(rows,'date','revenue_cents'),regions=aggregate(rows,'region','revenue_cents').sort((a,b)=>b.value-a.value),cats=aggregate(rows,'category','revenue_cents');return `<div class="kpis">${kpi('Net revenue',money(t.rev),trend(t.rev,p.rev))}${kpi('Gross profit',t.missing?'Incomplete':money(t.profit),t.missing?`${t.missing} lines missing cost · known portion ${money(t.profit)}`:trend(t.profit,p.profit))}${kpi('Gross margin',t.missing?'Unavailable':pct(t.profit/t.rev),t.missing?'Resolve missing costs before relying on margin':'Ratio of total gross profit to net revenue',true)}${kpi('Potential price shortfall',money(t.short),'Eligible sales only · investigation estimate')}</div><div class="grid"><div class="card"><h2>Revenue through the month</h2><p class="sub">Daily net revenue, including returns</p>${lineChart(daily,{moneyAxis:true})}<div class="legend"><span><i style="background:#2b7963"></i>Net revenue</span><span>${number(t.units)} gross units sold</span></div></div><div class="card"><h2>Revenue by region</h2><p class="sub">Contribution within the selected scope</p>${regions.map(r=>`<div class="bar-row"><span>${esc(r.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${r.value/Math.max(...regions.map(x=>x.value))*100}%"></div></div><strong>${money(r.value)}</strong></div>`).join('')}<div class="insight">${pct(t.matched/t.lines)} of lines have exactly one applicable contract. Unmatched and ambiguous records remain in revenue.</div></div></div><div class="card"><div class="section-title"><div><h2>Category economics</h2><p class="sub">A consistent view from transaction to finance</p></div><span class="mini">${number(t.lines)} transaction lines</span></div><div class="table-wrap"><table><thead><tr><th>CATEGORY</th><th class="num">NET REVENUE</th><th class="num">GROSS PROFIT</th><th class="num">MARGIN</th><th class="num">POTENTIAL SHORTFALL</th><th>DATA STATUS</th></tr></thead><tbody>${cats.map(c=>{const x=totals(rows.filter(r=>r.category===c.label));return `<tr><td><strong>${esc(c.label)}</strong></td><td class="num">${money(x.rev)}</td><td class="num">${x.missing?'Incomplete':money(x.profit)}</td><td class="num">${x.missing?'—':pct(x.profit/x.rev)}</td><td class="num">${money(x.short)}</td><td><span class="tag ${x.missing?'':'good'}">${x.missing?'Missing costs':'Cost complete'}</span></td></tr>`;}).join('')}</tbody></table></div></div>`;}
function bridge(){const curr=filtered(),prior=filtered(previous());if(sum(curr,'missing_cost_rows')||sum(prior,'missing_cost_rows'))return `<div class="note">Margin attribution is unavailable because one of the selected periods has missing costs. Select August or September to inspect a complete comparison.</div>`;const items=[...new Set([...curr,...prior].map(r=>r.product_id))];const Q0=sum(prior,'sale_units'),Q1=sum(curr,'sale_units');let volume=0,mix=0,price=0,cost=0;for(const id of items){const a=prior.filter(r=>r.product_id===id),b=curr.filter(r=>r.product_id===id),q0=sum(a,'sale_units'),q1=sum(b,'sale_units');if(!q0||!q1) return '<div class="note">Comparable product volumes are required.</div>';let p0=sum(a,'sale_revenue_cents')/q0,p1=sum(b,'sale_revenue_cents')/q1,c0=sum(a,'sale_known_cogs_cents')/q0,c1=sum(b,'sale_known_cogs_cents')/q1;volume+=(Q1-Q0)*(q0/Q0)*(p0-c0);mix+=Q1*(q1/Q1-q0/Q0)*(p0-c0);price+=q1*(p1-p0);cost-=q1*(c1-c0);}const a=totals(prior),b=totals(curr),ret=(b.profit-(sum(curr,'sale_revenue_cents')-sum(curr,'sale_known_cogs_cents')))-(a.profit-(sum(prior,'sale_revenue_cents')-sum(prior,'sale_known_cogs_cents')));const parts=[['Volume',volume],['Product mix',mix],['Net selling price',price],['Unit cost',cost],['Returns',ret]];return `<div class="kpis">${kpi('Previous gross profit',money(a.profit),previous())}${kpi('Current gross profit',money(b.profit),$('#month').value)}${kpi('Change in profit',money(b.profit-a.profit),'Exact bridge, before rounding',true)}${kpi('Reconciliation residual',money(b.profit-a.profit-parts.reduce((s,r)=>s+r[1],0),2),'Expected $0.00')}</div><div class="grid equal"><div class="card"><h2>What moved gross profit?</h2><p class="sub">Sequential price–volume–mix–cost attribution</p>${parts.map(([label,v])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.abs(v)/Math.max(...parts.map(x=>Math.abs(x[1])),1)*100}%;background:${v<0?'#b98259':'#317d68'}"></div></div><strong class="${v<0?'negative':'positive'}">${v>=0?'+':''}${money(v)}</strong></div>`).join('')}</div><div class="card"><h2>Method and interpretation</h2><div class="metric-list"><p><strong>Volume:</strong> total unit change at prior product shares and prior unit margins.</p><p><strong>Mix:</strong> current units redistributed across products at prior unit margins.</p><p><strong>Price / cost:</strong> unit price and cost changes applied to current product units.</p><p><strong>Returns:</strong> change in returned gross profit, separate from gross sales.</p></div><div class="insight">This is an accounting decomposition, not proof of causality. Compare September with August, then filter West / Personal care to investigate the seeded price change.</div></div></div>`;}
function exceptionRows(){return DATA.exceptions.filter(r=>r.date.startsWith($('#month').value)&&($('#region').value==='All'||r.region===$('#region').value)&&($('#category').value==='All'||r.category===$('#category').value)&&JSON.stringify(r).toLowerCase().includes(query.toLowerCase()));}
function exceptions(){const rows=exceptionRows(),pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages-1);return `<div class="note">Potential shortfall is a price difference requiring review. It is not confirmed leakage, collectible debt, or recovered revenue. Authorized overrides and returns are excluded.</div><div class="card"><div class="section-title"><div><h2>Investigation queue</h2><p class="sub">${number(rows.length)} records · sorted by date, then potential shortfall</p></div><input id="search" class="search" aria-label="Search exceptions" placeholder="Search product, reason, ID…" value="${esc(query)}"></div><div class="table-wrap"><table><thead><tr><th>TRANSACTION / DATE</th><th>STORE / PRODUCT</th><th>REASON</th><th class="num">ACTUAL</th><th class="num">EXPECTED</th><th class="num">SHORTFALL</th></tr></thead><tbody>${rows.slice(page*12,(page+1)*12).map(r=>`<tr><td><strong>${esc(r.transaction_id)} / ${r.line_id}</strong><br><span class="mini">${r.date}</span></td><td>${esc(r.store)}<br><span class="mini">${esc(r.product)}</span></td><td><span class="tag">${esc(r.reason)}</span></td><td class="num">${money(r.revenue_cents,2)}</td><td class="num">${r.expected_cents===null?'Unknown':money(r.expected_cents,2)}</td><td class="num">${r.shortfall_cents===null?'Unknown':money(r.shortfall_cents,2)}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No exceptions match these filters.</div>':''}</div><div class="pager"><button id="prev" class="secondary" ${page===0?'disabled':''}>Previous</button><span>${page+1} / ${pages}</span><button id="next" class="secondary" ${page===pages-1?'disabled':''}>Next</button></div></div>`;}
function forecast(){const f=DATA.forecast;return `<div class="note">Forecast scope: all stores and categories, as of 31 October 2026. Dashboard filters do not change this model. Results describe synthetic data, not real-world forecasting performance.</div><div class="kpis">${kpi('Selected method',f.selected==='weekday_trend'?'Weekday trend':'Seasonal naïve','Selected using three validation folds')}${kpi('Holdout WAPE',pct(f.test_wape[f.selected]),`${f.test_start} → ${f.test_end}`,true)}${kpi('Baseline WAPE',pct(f.test_wape.seasonal),'Repeat the last observed week')}${kpi('28-day volume forecast',number(sum(f.future,'units')),'Gross sale units · returns excluded')}</div><div class="grid equal"><div class="card"><h2>Next 28 days</h2><p class="sub">Central estimate with empirical uncertainty bounds in export</p>${lineChart(f.future.map(r=>({label:r.date,value:r.units})),{second:f.future.map(r=>({value:r.upper}))})}<div class="legend"><span><i style="background:#317d68"></i>Forecast</span><span><i style="background:#c49358"></i>Upper empirical bound</span></div><p class="sub">${esc(f.interval)}. Holdout coverage: ${pct(f.test_interval_coverage)}. Download forecast CSV for both bounds.</p></div><div class="card"><h2>Margin scenario planner</h2><p class="sub">Uses complete September economics, all stores. Independent assumptions; no demand elasticity model.</p><div class="slider-row"><label for="price">Selling price change</label><input type="range" id="price" min="-10" max="10" value="0" step="0.5"><output id="price-out">0%</output></div><div class="slider-row"><label for="cost">Unit cost change</label><input type="range" id="cost" min="-10" max="15" value="0" step="0.5"><output id="cost-out">0%</output></div><div class="slider-row"><label for="volume">Volume change</label><input type="range" id="volume" min="-20" max="20" value="0"><output id="volume-out">0%</output></div><div class="scenario-result"><span class="mini">Illustrative gross sale profit · excludes returns</span><strong id="scenario-value"></strong><p class="mini" id="scenario-detail"></p></div></div></div>`;}
function quality(){const m=DATA.meta;return `<div class="kpis">${kpi('Source rows',number(m.raw_rows),'Deterministic synthetic source')}${kpi('Accepted rows',number(m.accepted_rows),'Unique transaction / line grain',true)}${kpi('Quarantined rows',number(m.rejected_rows),'Excluded with auditable reason')}${kpi('Revenue reconciliation',money(m.raw_revenue_cents-m.accepted_revenue_cents-m.rejected_revenue_cents,2),'Raw − accepted − quarantined')}</div><div class="grid"><div class="card"><h2>Validation register</h2><p class="sub">Whole dataset · warnings are intentionally seeded data issues</p>${DATA.checks.map(c=>`<div class="quality-row"><span class="tag ${c.status==='PASS'?'good':c.status==='INFO'?'info':''}">${c.status}</span><div><strong>${esc(c.name)}</strong><p>${esc(c.detail)}</p></div>${c.count?`<span class="count">${number(c.count)}</span>`:''}</div>`).join('')}</div><div class="card"><h2>Traceability & controls</h2><div class="metric-list"><p><strong>Seed:</strong> ${m.seed}</p><p><strong>Period:</strong> ${m.start} to ${m.end}</p><p><strong>Currency:</strong> USD, tax excluded</p><p><strong>Money:</strong> integer cents in the pipeline</p><p><strong>Access:</strong> hosting gate; no row-level authorization in this static demo</p><p><strong>Refresh:</strong> rebuild and redeploy; no live scheduled source</p></div><p class="sub">Source fingerprint (SHA-256)</p><code style="font-size:10px;overflow-wrap:anywhere">${m.fingerprint}</code><div class="insight">The demo contains no employer records, customer identities, patient data, or real contract terms.</div></div></div>`;}
function brief(){const f=DATA.forecast;return `<div class="section-title"><p class="sub">Presentation mode · six slides · print to save as PDF</p><button id="print" class="secondary">Print presentation ↗</button></div>${[
['01 / THE DECISION','Revenue is only half the story.','MarginLens helps a fictional retail finance team understand gross profit changes, investigate price exceptions, and evaluate commercial scenarios. The decision: which products and stores deserve review before the next negotiation?'],
['02 / THE FOUNDATION','One trusted financial view.',`${number(DATA.meta.accepted_rows)} accepted transaction lines across six stores and nine products. Source-to-mart totals reconcile exactly in cents. Duplicates and unknown stores are quarantined; missing costs and ambiguous contracts remain visible.`],
['03 / THE INVESTIGATION','Separate price, volume, mix, and cost.','Demonstrate September versus August. Filter West / Personal care to inspect the intentional price reduction. Home essentials includes an intentional cost increase. These are seeded scenarios, not discovered real-world commercial findings.'],
['04 / THE CONTROL','An exception is a starting point, not a recovery claim.','Review the contract exception queue. Every record includes its transaction, date, store, product, actual revenue, and expected revenue where a unique contract exists. Authorized overrides and returns are excluded from potential shortfall.'],
['05 / THE OUTLOOK','Forecast with a benchmark and a holdout.',`Three rolling validation folds select the forecasting method. On the final 28-day holdout, selected-method WAPE is ${pct(f.test_wape[f.selected])}, compared with ${pct(f.test_wape.seasonal)} for the seasonal baseline. Synthetic-data results do not establish client performance. Scenario sliders are assumptions, not causal predictions.`],
['06 / THE PILOT','Move from demonstration to a measured pilot.','Agree on metric definitions and pricing exceptions. Map authorized client sources. Run historical reconciliation and access testing. Validate forecasts on client holdouts. Pilot with finance reviewers and measure confirmed exceptions, investigation time, and forecast error before claiming business value.']
].map(([n,t,b])=>`<article class="brief-slide"><p class="eyebrow">${n}</p><h2>${t}</h2><p>${b}</p></article>`).join('')}`;}
const titles={overview:['THE COMMERCIAL PICTURE','Performance overview','Follow the revenue. Understand the margin.'],drivers:['EXPLAIN THE CHANGE','Margin drivers','A reconciled bridge from last month to this month.'],exceptions:['FROM SIGNAL TO REVIEW','Contract exceptions','Trace potential pricing issues to their source.'],forecast:['PLAN WITH CONTEXT','Forecast & scenarios','Test assumptions. Keep uncertainty visible.'],quality:['CONFIDENCE BY DESIGN','Data trust','Every reported number starts with a control.'],brief:['CLIENT PRESENTATION','The MarginLens briefing','A practical demonstration and a path to a measured pilot.']};
function render(){const t=titles[view];$('#kicker').textContent=t[0];$('#title').textContent=t[1];$('#subtitle').textContent=t[2];$('.filters').style.display=['quality','brief','forecast'].includes(view)?'none':'flex';$('#app').innerHTML=({overview,drivers:bridge,exceptions,forecast,quality,brief}[view])();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='exceptions'){$('#search').addEventListener('input',e=>{query=e.target.value;page=0;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});$('#prev').onclick=()=>{page--;render();};$('#next').onclick=()=>{page++;render();};}if(view==='forecast'){document.querySelectorAll('input[type=range]').forEach(e=>e.oninput=scenario);scenario();}if(view==='brief')$('#print').onclick=()=>window.print();}
function scenario(){let p=+$('#price').value/100,c=+$('#cost').value/100,v=+$('#volume').value/100;['price','cost','volume'].forEach(id=>$('#'+id+'-out').textContent=$('#'+id).value+'%');const rows=DATA.daily.filter(r=>r.date.startsWith('2026-09'));const rev=sum(rows,'sale_revenue_cents')*(1+p)*(1+v),cost=sum(rows,'sale_known_cogs_cents')*(1+c)*(1+v);$('#scenario-value').textContent=money(rev-cost);$('#scenario-detail').textContent=`Revenue ${money(rev)} · gross sale margin ${pct((rev-cost)/rev)} · hypothetical, not forecast`;}
function csv(rows){if(!rows.length){alert('No rows to export for this selection.');return;}const keys=Object.keys(rows[0]);const safe=v=>{let s=String(v??'');if(/^[=+@\t\r]/.test(s)||(/^-/ .test(s)&&!Number.isFinite(Number(s))))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob([[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`marginlens-${view}-${$('#month').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;page=0;location.hash=view;render();});['month','region','category'].forEach(id=>$('#'+id).onchange=()=>{page=0;render();});$('#reset').onclick=()=>{$('#month').value='2026-08';$('#region').value='All';$('#category').value='All';query='';page=0;render();};$('#export').onclick=()=>csv(view==='exceptions'?exceptionRows():view==='forecast'?DATA.forecast.future:view==='quality'?DATA.checks:filtered());fetch('data.json').then(r=>{if(!r.ok)throw Error('Snapshot unavailable');return r.json();}).then(data=>{DATA=data;if(titles[location.hash.slice(1)])view=location.hash.slice(1);render();}).catch(e=>{$('#app').textContent='Unable to load the snapshot. Refresh the page or contact the project owner. '+e.message;});
